#include <bits/stdc++.h>
using namespace std;
const int MOD=1e9+7;
const int MAX=1<<20;
int n,mask_limit,answer,p1_acc[MAX],p2_acc[MAX];
int grid_flag[10][10],grid_a[10][10],h_mask[10][10][10];

int power(int base, int exp) {
    int res=1;
    while (exp > 0) {
        if (exp & 1) res=1LL*res*base%MOD;
        base=1LL*base*base%MOD;
        exp>>=1;
    }
    return res;
}

int inverse(int x) { return power(x,MOD-2); }

bool verify_triplet(int x,int y,int z) {
    int arr[3]={x,y,z},perm[3]={0,1,2};
    do {
        if (grid_flag[arr[perm[0]]][1] && grid_flag[arr[perm[1]]][2] && grid_flag[arr[perm[2]]][3]) return true;
    } while (next_permutation(perm,perm+3));
    return false;
}

void dfs_first(int P,int x,int y) {
    if (x==7 && y==1) {
        int state=0;
        for (int i=1; i<=6; i++)
            for (int j=i+1; j<=6; j++)
                for (int k=j+1; k<=6; k++) 
                    if (verify_triplet(i,j,k)) {
                        int X=1;
                        while (X==i || X==j || X==k) X++;
                        int Y=X+1;
                        while (Y==i || Y==j || Y==k) Y++;
                        int Z=Y+1;
                        while (Z==i || Z==j || Z==k) Z++;
                        state|=h_mask[X][Y][Z];
                    }
        p1_acc[state]=(p1_acc[state]+P)%MOD;
        return;
    }
    grid_flag[x][y]=1;
    if (y==3) dfs_first(1LL*P*grid_a[x][y]%MOD,x+1,1);
    else dfs_first(1LL*P*grid_a[x][y]%MOD,x,y+1);
    grid_flag[x][y]=0;
    if (y==3) dfs_first(1LL*P*(MOD+1-grid_a[x][y])%MOD,x+1,1);
    else dfs_first(1LL*P*(MOD+1-grid_a[x][y])%MOD,x,y+1);
}

void dfs_second(int P,int x,int y) {
    if (x==7 && y==4) {
        int state=0;
        for (int i=1; i<=6; i++)
            for (int j=i+1; j<=6; j++)
                for (int k=j+1; k<=6; k++) 
                    if (verify_triplet(i,j,k)) state|=h_mask[i][j][k];
        p2_acc[state]=(p2_acc[state]+P)%MOD;
        answer=(answer+1LL*p1_acc[mask_limit^state]*P%MOD)%MOD;
        return;
    }
    grid_flag[x][y-3]=1;
    if (y==6) dfs_second(1LL*P*grid_a[x][y]%MOD,x+1,4);
    else dfs_second(1LL*P*grid_a[x][y]%MOD,x,y+1);
    grid_flag[x][y-3]=0;
    if (y==6) dfs_second(1LL*P*(MOD+1-grid_a[x][y])%MOD,x+1,4);
    else dfs_second(1LL*P*(MOD+1-grid_a[x][y])%MOD,x,y+1);
}

int main() {
    scanf("%d",&n);
    for (int i=1; i<=n; i++)
        for (int j=1; j<=n; j++)
            scanf("%d",&grid_a[i][j]),grid_a[i][j]=1LL*grid_a[i][j]*inverse(100)%MOD;
    for (int i=n+1; i<=6; i++) grid_a[i][i]=1;
    int total=0;
    for (int i=1; i<=6; i++)
        for (int j=i+1; j<=6; j++)
            for (int k=j+1; k<=6; k++) 
                h_mask[i][j][k]=1<<total++;
    dfs_first(1,1,1);
    mask_limit=(1<<20)-1;
    for (int i=0; i<=19; i++)
        for (int j=0; j<=mask_limit; j++) 
            if (j>>i&1) p1_acc[j]=(p1_acc[j]+p1_acc[j^1<<i])%MOD;
    dfs_second(1,1,4);
    answer=(MOD+1-answer)%MOD;
    printf("%d\n",answer);
    return 0;
}
